package com.casms.servicepackage.controller;

import com.casms.common.response.ApiResponse;
import com.casms.servicepackage.entity.*;
import com.casms.servicepackage.enums.*;
import com.casms.servicepackage.service.ServicepackageService;
import com.casms.servicepackage.service.ServiceRequestService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.access.prepost.PreAuthorize;
import java.math.BigDecimal;
import java.util.*;

@RestController @RequestMapping("/servicepackage") @RequiredArgsConstructor
public class ServicepackageController {
 private final ServicepackageService service;
 private final ServiceRequestService serviceRequests;
 public record ServiceCatalogDto(@NotBlank @Size(max=50) String serviceCode,@NotBlank @Size(max=200) String serviceName,@Size(max=1000) String description,@NotBlank @Size(max=50) String serviceType,@DecimalMin("0.0") BigDecimal price,@Size(min=3,max=3) String currencyCode,@Positive Integer capacity){}
 public record ProductDto(@NotBlank @Size(max=50) String productCode,@NotBlank @Size(max=200) String productName,@Size(max=1000) String description,@NotBlank @Size(max=50) String productType,@NotNull @DecimalMin("0.0") BigDecimal unitPrice,@NotBlank @Size(min=3,max=3) String currencyCode){}
 public record PackageDto(@NotBlank @Size(max=50) String packageCode,@NotBlank @Size(max=200) String packageName,@Size(max=1000) String description,@NotNull TourPackageType packageType,@NotNull @DecimalMin("0.0") BigDecimal price,@NotBlank @Size(min=3,max=3) String currencyCode,java.time.LocalDate startDate,java.time.LocalDate endDate){}
 public record ServiceRequestDto(@NotNull UUID serviceId,UUID bookingPassengerId,@NotNull @Positive Integer quantity,@Size(max=500) String note){}
 public record ServiceRequestUpdateDto(@NotNull @Positive Integer quantity,@Size(max=500) String note){}
 public record ServiceRequestView(UUID id,UUID passengerId,UUID serviceId,UUID bookingId,UUID bookingPassengerId,Integer quantity,String note,String status,UUID assignedUserId,java.time.Instant requestTime,java.time.Instant completedAt){static ServiceRequestView of(com.casms.servicepackage.entity.ServiceRequest r){return new ServiceRequestView(r.getServiceRequestId(),r.getPassenger().getPassengerId(),r.getService().getServiceId(),r.getBooking()==null?null:r.getBooking().getBookingId(),r.getBookingPassenger()==null?null:r.getBookingPassenger().getBookingPassengerId(),r.getQuantity(),r.getNote(),r.getStatus().name(),r.getAssignedUser()==null?null:r.getAssignedUser().getUserId(),r.getRequestTime(),r.getCompletedAt());}}
 public record PackageAssignmentDto(@NotNull UUID tourPackageId){}
 public record BenefitDto(@NotNull BenefitType benefitType){}
 public record AssignmentView(UUID bookingPassengerId,UUID packageId,java.math.BigDecimal agreedPrice,String currency,java.time.Instant assignedAt){static AssignmentView of(BookingPassengerPackage a){return new AssignmentView(a.getBookingPassengerId(),a.getTourPackage().getTourPackageId(),a.getAgreedPrice(),a.getCurrency(),a.getAssignedAt());}}
 public record PackageServiceView(UUID packageId,UUID serviceId,BenefitType benefitType){static PackageServiceView of(TourPackageService x){return new PackageServiceView(x.getTourPackage().getTourPackageId(),x.getService().getServiceId(),x.getBenefitType());}}
 public record PackageActivityView(UUID packageId,UUID activityId,BenefitType benefitType){static PackageActivityView of(TourPackageActivity x){return new PackageActivityView(x.getTourPackage().getTourPackageId(),x.getOnboardActivity().getOnboardActivityId(),x.getBenefitType());}}
 public record PackageExcursionView(UUID packageId,UUID excursionId,BenefitType benefitType){static PackageExcursionView of(TourPackageExcursion x){return new PackageExcursionView(x.getTourPackage().getTourPackageId(),x.getShoreExcursion().getShoreExcursionId(),x.getBenefitType());}}
 public record ServiceView(UUID id,String code,String name,String description,String type,BigDecimal price,String currency,Integer capacity,String status){static ServiceView of(com.casms.servicepackage.entity.Service s){return new ServiceView(s.getServiceId(),s.getServiceCode(),s.getServiceName(),s.getDescription(),s.getServiceType(),s.getPrice(),s.getCurrencyCode(),s.getCapacity(),s.getStatus().name());}}
 public record ProductView(UUID id,String code,String name,String description,String type,BigDecimal price,String currency,String status){static ProductView of(Product p){return new ProductView(p.getProductId(),p.getProductCode(),p.getProductName(),p.getDescription(),p.getProductType(),p.getUnitPrice(),p.getCurrencyCode(),p.getStatus().name());}}
 public record PackageView(UUID id,String code,String name,String description,String type,BigDecimal price,String currency,String status,java.time.LocalDate startDate,java.time.LocalDate endDate){static PackageView of(TourPackage p){return new PackageView(p.getTourPackageId(),p.getPackageCode(),p.getPackageName(),p.getDescription(),p.getPackageType().name(),p.getPrice(),p.getCurrencyCode(),p.getStatus().name(),p.getStartDate(),p.getEndDate());}}
 public record ServiceAvailabilityView(UUID serviceId,Integer requestedQuantity,boolean available){}
 public record PackageBenefitsView(PackageView packageInfo,List<PackageServiceView> services,List<PackageActivityView> activities,List<PackageExcursionView> excursions){}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).SERVICE_READ)") @GetMapping("/services") public ApiResponse<List<ServiceView>> services(){return ApiResponse.success(service.services().stream().map(ServiceView::of).toList());}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).SERVICE_READ)") @GetMapping("/services/{id}") public ApiResponse<ServiceView> service(@PathVariable UUID id){return ApiResponse.success(ServiceView.of(service.service(id)));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).SERVICE_READ)") @GetMapping("/services/{id}/availability") public ApiResponse<ServiceAvailabilityView> serviceAvailability(@PathVariable UUID id,@RequestParam(defaultValue="1") Integer quantity){return ApiResponse.success(new ServiceAvailabilityView(id,quantity,service.serviceAvailable(id,quantity)));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).SERVICE_READ)") @PostMapping("/services/{id}/schedule-check") public org.springframework.http.ResponseEntity<ApiResponse<Void>> serviceScheduleCheck(@PathVariable UUID id){service.service(id);return org.springframework.http.ResponseEntity.status(HttpStatus.NOT_IMPLEMENTED).body(ApiResponse.error("Service has no schedule fields or schedule relation in the current schema."));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).SERVICE_CREATE)") @PostMapping("/services") @ResponseStatus(HttpStatus.CREATED) public ApiResponse<ServiceView> createService(@Valid @RequestBody ServiceCatalogDto r){var s=new com.casms.servicepackage.entity.Service();apply(s,r);return ApiResponse.success(ServiceView.of(service.saveService(s)));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).SERVICE_UPDATE)") @PutMapping("/services/{id}") public ApiResponse<ServiceView> updateService(@PathVariable UUID id,@Valid @RequestBody ServiceCatalogDto r){var s=service.service(id);apply(s,r);return ApiResponse.success(ServiceView.of(service.saveService(s)));}
 @PreAuthorize("hasAnyPermission(T(com.casms.identity.enums.Permission).SERVICE_ACTIVATE, T(com.casms.identity.enums.Permission).SERVICE_SUSPEND)") @PostMapping("/services/{id}/{action}") public ApiResponse<ServiceView> serviceStatus(@PathVariable UUID id,@PathVariable String action){return ApiResponse.success(ServiceView.of(service.serviceStatus(id,action)));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).SERVICE_DELETE_UNUSED)") @DeleteMapping("/services/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteService(@PathVariable UUID id){service.deleteService(id);}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PRODUCT_MANAGE)") @GetMapping("/products") public ApiResponse<List<ProductView>> products(){return ApiResponse.success(service.products().stream().map(ProductView::of).toList());}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PRODUCT_MANAGE)") @GetMapping("/products/{id}") public ApiResponse<ProductView> product(@PathVariable UUID id){return ApiResponse.success(ProductView.of(service.product(id)));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PRODUCT_MANAGE)") @PostMapping("/products") @ResponseStatus(HttpStatus.CREATED) public ApiResponse<ProductView> createProduct(@Valid @RequestBody ProductDto r){var p=new Product();apply(p,r);return ApiResponse.success(ProductView.of(service.saveProduct(p)));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PRODUCT_MANAGE)") @PutMapping("/products/{id}") public ApiResponse<ProductView> updateProduct(@PathVariable UUID id,@Valid @RequestBody ProductDto r){var p=service.product(id);apply(p,r);return ApiResponse.success(ProductView.of(service.saveProduct(p)));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PRODUCT_MANAGE)") @PostMapping("/products/{id}/status/{action}") public ApiResponse<ProductView> productStatus(@PathVariable UUID id,@PathVariable String action){return ApiResponse.success(ProductView.of(service.productStatus(id,action)));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PRODUCT_SALE)") @PostMapping("/products/{id}/sales") public org.springframework.http.ResponseEntity<ApiResponse<Void>> recordSale(@PathVariable UUID id){service.product(id);return org.springframework.http.ResponseEntity.status(HttpStatus.NOT_IMPLEMENTED).body(ApiResponse.error("Product sales are not represented by a product sale/POS workflow in the current schema."));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PRODUCT_MANAGE)") @DeleteMapping("/products/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteProduct(@PathVariable UUID id){service.deleteProduct(id);}
 @PreAuthorize("hasAnyPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_MANAGE, T(com.casms.identity.enums.Permission).TOUR_PACKAGE_ASSIGN)") @GetMapping("/packages") public ApiResponse<List<PackageView>> packages(){return ApiResponse.success(service.packages().stream().map(PackageView::of).toList());}
 @PreAuthorize("hasAnyPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_MANAGE, T(com.casms.identity.enums.Permission).TOUR_PACKAGE_ASSIGN)") @GetMapping("/packages/{id}") public ApiResponse<PackageView> tourPackage(@PathVariable UUID id){return ApiResponse.success(PackageView.of(service.tourPackage(id)));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_MANAGE)") @PostMapping("/packages") @ResponseStatus(HttpStatus.CREATED) public ApiResponse<PackageView> createPackage(@Valid @RequestBody PackageDto r){var p=new TourPackage();apply(p,r);return ApiResponse.success(PackageView.of(service.savePackage(p)));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_MANAGE)") @PutMapping("/packages/{id}") public ApiResponse<PackageView> updatePackage(@PathVariable UUID id,@Valid @RequestBody PackageDto r){var p=service.tourPackage(id);if(p.getStatus()!=TourPackageStatus.DRAFT)throw new IllegalStateException("Only draft packages can be edited");apply(p,r);return ApiResponse.success(PackageView.of(service.savePackage(p)));}
 @PreAuthorize("hasAnyPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_MANAGE, T(com.casms.identity.enums.Permission).TOUR_PACKAGE_ASSIGN)") @GetMapping("/packages/{id}/benefits") public ApiResponse<PackageBenefitsView> packageBenefits(@PathVariable UUID id){return ApiResponse.success(new PackageBenefitsView(PackageView.of(service.tourPackage(id)),service.packageServices(id).stream().map(PackageServiceView::of).toList(),service.packageActivities(id).stream().map(PackageActivityView::of).toList(),service.packageExcursions(id).stream().map(PackageExcursionView::of).toList()));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_MANAGE)") @PostMapping("/packages/{id}/{action}") public ApiResponse<PackageView> packageStatus(@PathVariable UUID id,@PathVariable String action){return ApiResponse.success(PackageView.of(service.packageStatus(id,action)));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_MANAGE)") @DeleteMapping("/packages/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deletePackage(@PathVariable UUID id){service.deletePackage(id);}
 private static void apply(com.casms.servicepackage.entity.Service s,ServiceCatalogDto r){s.setServiceCode(r.serviceCode());s.setServiceName(r.serviceName());s.setDescription(r.description());s.setServiceType(r.serviceType());s.setPrice(r.price());s.setCurrencyCode(r.currencyCode());s.setCapacity(r.capacity());}
 private static void apply(Product p,ProductDto r){p.setProductCode(r.productCode());p.setProductName(r.productName());p.setDescription(r.description());p.setProductType(r.productType());p.setUnitPrice(r.unitPrice());p.setCurrencyCode(r.currencyCode());}
 private static void apply(TourPackage p,PackageDto r){p.setPackageCode(r.packageCode());p.setPackageName(r.packageName());p.setDescription(r.description());p.setPackageType(r.packageType());p.setPrice(r.price());p.setCurrencyCode(r.currencyCode());p.setStartDate(r.startDate());p.setEndDate(r.endDate());}

 @PreAuthorize("hasAnyPermission(T(com.casms.identity.enums.Permission).SERVICE_REQUEST_READ, T(com.casms.identity.enums.Permission).SERVICE_REQUEST_CREATE)") @GetMapping("/requests") public ApiResponse<List<ServiceRequestView>> requests(org.springframework.security.core.Authentication auth){var principal=(com.casms.security.principal.CasmsPrincipal)auth.getPrincipal();return ApiResponse.success(serviceRequests.list(principal.getUserId(),principal.isStaff()).stream().map(ServiceRequestView::of).toList());}
 @PreAuthorize("hasAnyPermission(T(com.casms.identity.enums.Permission).SERVICE_REQUEST_READ, T(com.casms.identity.enums.Permission).SERVICE_REQUEST_CREATE)") @GetMapping("/requests/{id}") public ApiResponse<ServiceRequestView> request(@PathVariable UUID id,org.springframework.security.core.Authentication auth){var principal=(com.casms.security.principal.CasmsPrincipal)auth.getPrincipal();return ApiResponse.success(ServiceRequestView.of(serviceRequests.get(id,principal.getUserId(),principal.isStaff())));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).SERVICE_REQUEST_CREATE)") @PostMapping("/requests") @ResponseStatus(HttpStatus.CREATED) public ApiResponse<ServiceRequestView> createRequest(@Valid @RequestBody ServiceRequestDto r,org.springframework.security.core.Authentication auth){var p=(com.casms.security.principal.CasmsPrincipal)auth.getPrincipal();return ApiResponse.success(ServiceRequestView.of(serviceRequests.create(p.getUserId(),r.serviceId(),r.bookingPassengerId(),r.quantity(),r.note())));}
 @PreAuthorize("hasAnyPermission(T(com.casms.identity.enums.Permission).SERVICE_REQUEST_CREATE, T(com.casms.identity.enums.Permission).SERVICE_REQUEST_EXECUTE)") @PutMapping("/requests/{id}") public ApiResponse<ServiceRequestView> updateRequest(@PathVariable UUID id,@Valid @RequestBody ServiceRequestUpdateDto r,org.springframework.security.core.Authentication auth){var p=(com.casms.security.principal.CasmsPrincipal)auth.getPrincipal();return ApiResponse.success(ServiceRequestView.of(serviceRequests.updatePending(id,p.getUserId(),p.isStaff(),r.quantity(),r.note())));}
 @PreAuthorize("hasAnyPermission(T(com.casms.identity.enums.Permission).SERVICE_REQUEST_ASSIGN, T(com.casms.identity.enums.Permission).SERVICE_REQUEST_EXECUTE)") @PostMapping("/requests/{id}/actions/{action}") public ApiResponse<ServiceRequestView> serviceRequestAction(@PathVariable UUID id,@PathVariable String action,org.springframework.security.core.Authentication auth){var p=(com.casms.security.principal.CasmsPrincipal)auth.getPrincipal();return ApiResponse.success(ServiceRequestView.of(serviceRequests.transition(id,p.getUserId(),action)));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).SERVICE_REQUEST_CREATE)") @PostMapping("/requests/{id}/cancel") public ApiResponse<ServiceRequestView> cancelRequest(@PathVariable UUID id,org.springframework.security.core.Authentication auth){var p=(com.casms.security.principal.CasmsPrincipal)auth.getPrincipal();var r=serviceRequests.get(id,p.getUserId(),p.isStaff());return ApiResponse.success(ServiceRequestView.of(serviceRequests.transition(id,p.getUserId(),"cancel")));}

 @PreAuthorize("hasAnyPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_ASSIGN, T(com.casms.identity.enums.Permission).TOUR_PACKAGE_MANAGE)") @GetMapping("/package-assignments") public ApiResponse<List<AssignmentView>> packageAssignments(@RequestParam(required=false) UUID bookingId,org.springframework.security.core.Authentication auth){var p=(com.casms.security.principal.CasmsPrincipal)auth.getPrincipal();return ApiResponse.success(service.packageAssignments(bookingId,p.getUserId(),p.isStaff()).stream().map(AssignmentView::of).toList());}
 @PreAuthorize("hasAnyPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_ASSIGN, T(com.casms.identity.enums.Permission).TOUR_PACKAGE_MANAGE)") @GetMapping("/package-assignments/{bookingPassengerId}") public ApiResponse<AssignmentView> packageAssignment(@PathVariable UUID bookingPassengerId,org.springframework.security.core.Authentication auth){var p=(com.casms.security.principal.CasmsPrincipal)auth.getPrincipal();return ApiResponse.success(AssignmentView.of(service.packageAssignment(bookingPassengerId,p.getUserId(),p.isStaff())));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_ASSIGN)") @PostMapping("/package-assignments/{bookingPassengerId}") @ResponseStatus(HttpStatus.CREATED) public ApiResponse<AssignmentView> assignPackage(@PathVariable UUID bookingPassengerId,@Valid @RequestBody PackageAssignmentDto r,org.springframework.security.core.Authentication auth){var p=(com.casms.security.principal.CasmsPrincipal)auth.getPrincipal();return ApiResponse.success(AssignmentView.of(service.assignPackage(bookingPassengerId,r.tourPackageId(),p.getUserId(),p.isStaff())));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_ASSIGN)") @PutMapping("/package-assignments/{bookingPassengerId}") public ApiResponse<AssignmentView> changePackage(@PathVariable UUID bookingPassengerId,@Valid @RequestBody PackageAssignmentDto r,org.springframework.security.core.Authentication auth){var p=(com.casms.security.principal.CasmsPrincipal)auth.getPrincipal();return ApiResponse.success(AssignmentView.of(service.changePackage(bookingPassengerId,r.tourPackageId(),p.getUserId(),p.isStaff())));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_ASSIGN)") @DeleteMapping("/package-assignments/{bookingPassengerId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void removePackage(@PathVariable UUID bookingPassengerId,org.springframework.security.core.Authentication auth){var p=(com.casms.security.principal.CasmsPrincipal)auth.getPrincipal();service.removePackageAssignment(bookingPassengerId,p.getUserId(),p.isStaff());}
 @PreAuthorize("hasAnyPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_MANAGE, T(com.casms.identity.enums.Permission).PACKAGE_COMPONENT_MANAGE)") @GetMapping("/packages/{id}/services") public ApiResponse<List<PackageServiceView>> packageServices(@PathVariable UUID id){return ApiResponse.success(service.packageServices(id).stream().map(PackageServiceView::of).toList());}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PACKAGE_COMPONENT_MANAGE)") @PostMapping("/packages/{id}/services/{serviceId}") public ApiResponse<PackageServiceView> addPackageService(@PathVariable UUID id,@PathVariable UUID serviceId,@Valid @RequestBody BenefitDto r){return ApiResponse.success(PackageServiceView.of(service.addPackageService(id,serviceId,r.benefitType())));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PACKAGE_COMPONENT_MANAGE)") @PutMapping("/packages/{id}/services/{serviceId}") public ApiResponse<PackageServiceView> updatePackageService(@PathVariable UUID id,@PathVariable UUID serviceId,@Valid @RequestBody BenefitDto r){return ApiResponse.success(PackageServiceView.of(service.updatePackageService(id,serviceId,r.benefitType())));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PACKAGE_COMPONENT_MANAGE)") @DeleteMapping("/packages/{id}/services/{serviceId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void removePackageService(@PathVariable UUID id,@PathVariable UUID serviceId){service.removePackageService(id,serviceId);}
 @PreAuthorize("hasAnyPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_MANAGE, T(com.casms.identity.enums.Permission).PACKAGE_COMPONENT_MANAGE)") @GetMapping("/packages/{id}/activities") public ApiResponse<List<PackageActivityView>> packageActivities(@PathVariable UUID id){return ApiResponse.success(service.packageActivities(id).stream().map(PackageActivityView::of).toList());}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PACKAGE_COMPONENT_MANAGE)") @PostMapping("/packages/{id}/activities/{activityId}") public ApiResponse<PackageActivityView> addPackageActivity(@PathVariable UUID id,@PathVariable UUID activityId,@Valid @RequestBody BenefitDto r){return ApiResponse.success(PackageActivityView.of(service.addPackageActivity(id,activityId,r.benefitType())));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PACKAGE_COMPONENT_MANAGE)") @PutMapping("/packages/{id}/activities/{activityId}") public ApiResponse<PackageActivityView> updatePackageActivity(@PathVariable UUID id,@PathVariable UUID activityId,@Valid @RequestBody BenefitDto r){return ApiResponse.success(PackageActivityView.of(service.updatePackageActivity(id,activityId,r.benefitType())));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PACKAGE_COMPONENT_MANAGE)") @DeleteMapping("/packages/{id}/activities/{activityId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void removePackageActivity(@PathVariable UUID id,@PathVariable UUID activityId){service.removePackageActivity(id,activityId);}
 @PreAuthorize("hasAnyPermission(T(com.casms.identity.enums.Permission).TOUR_PACKAGE_MANAGE, T(com.casms.identity.enums.Permission).PACKAGE_COMPONENT_MANAGE)") @GetMapping("/packages/{id}/excursions") public ApiResponse<List<PackageExcursionView>> packageExcursions(@PathVariable UUID id){return ApiResponse.success(service.packageExcursions(id).stream().map(PackageExcursionView::of).toList());}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PACKAGE_COMPONENT_MANAGE)") @PostMapping("/packages/{id}/excursions/{excursionId}") public ApiResponse<PackageExcursionView> addPackageExcursion(@PathVariable UUID id,@PathVariable UUID excursionId,@Valid @RequestBody BenefitDto r){return ApiResponse.success(PackageExcursionView.of(service.addPackageExcursion(id,excursionId,r.benefitType())));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PACKAGE_COMPONENT_MANAGE)") @PutMapping("/packages/{id}/excursions/{excursionId}") public ApiResponse<PackageExcursionView> updatePackageExcursion(@PathVariable UUID id,@PathVariable UUID excursionId,@Valid @RequestBody BenefitDto r){return ApiResponse.success(PackageExcursionView.of(service.updatePackageExcursion(id,excursionId,r.benefitType())));}
 @PreAuthorize("hasPermission(T(com.casms.identity.enums.Permission).PACKAGE_COMPONENT_MANAGE)") @DeleteMapping("/packages/{id}/excursions/{excursionId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void removePackageExcursion(@PathVariable UUID id,@PathVariable UUID excursionId){service.removePackageExcursion(id,excursionId);}
}
